![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

When refactoring functions to defensively handle nullish inputs, ensure that strictly required dependencies (such as `identity`) are not assigned default values that would mask missing arguments, keeping them required.

```javascript
function buildActiveScopeBundle(row = {}, identity) {
  const questionPayload = readQuestionPayload(row) || {};
  const questionRef = buildTypedQuestionRef(identity?.question_id);
  const questionTypeRef = buildTypedQuestionTypeRef(
    normalizeNullableString(questionPayload.primary_question_type_id),
  );

  return {
    primary_topic_id: questionPayload.primary_topic_id ?? null,
    primary_topic_path: null,
    secondary_topics_in_scope: Array.isArray(questionPayload.secondary_topic_ids)
      ? cloneJson(questionPayload.secondary_topic_ids)
      : [],
    allowed_prerequisites: [],
    paper_context: isPlainObject(questionPayload.paper_scope) ? cloneJson(questionPayload.paper_scope) : null,
    mode: null,
    session_goal: null,
    current_anchor_kind: questionRef ? 'question' : null,
    current_anchor_ref: questionRef,
    current_question_ref: questionRef,
    current_question_type_ref: questionTypeRef,
  };
}
```

